mapper.select:
select e.equip_id, e.equip_cd, e.equip_nm, e.plant_cd, e.use_yn
  from mst_equip e

    (e.equip_cd like #{keyword} escape '\' or e.equip_nm ilike #{keyword} escape '\')
    and e.plant_cd = #{plantCd}

 order by e.use_yn desc, e.equip_cd
 limit #{limit}

select count(*) from cms_counter_reading r join cms_counter c on c.counter_id = r.counter_id
 where c.equip_id = #{equipId} and r.reset_yn = 'Y' and r.void_yn = 'N'
   and r.read_at >= #{from} and r.read_at < #{to}

mapper.sql:
from (
select 'MWO' as kind, m.mwo_id as src_id, m.reported_at as at, m.mwo_no as ref_no, m.title, m.status, m.mwo_type as sub_type, null::varchar as result, null::numeric as qty, null::varchar as unit, case when m.down_start_at is not null and m.down_end_at is not null then floor(extract(epoch from (m.down_end_at - m.down_start_at)) / 60)::int end as down_min, u.user_nm as by_nm, m.mwo_id from cms_mwo m left join sys_user u on u.user_id = m.requested_by where m.equip_id = #{equipId} and m.reported_at >= #{from} and m.reported_at < #{to}
union all
select 'CHK' as kind, r.run_id as src_id, coalesce(r.performed_at, r.due_date::timestamp at time zone #{zone}) as at, p.plan_cd as ref_no, t.tmpl_nm as title, r.status, null::varchar as sub_type, r.result, null::numeric as qty, null::varchar as unit, null::int as down_min, u.user_nm as by_nm, r.mwo_id from cms_chk_run r join cms_pm_plan p on p.plan_id = r.plan_id join cms_chk_tmpl t on t.tmpl_id = r.tmpl_id left join sys_user u on u.user_id = r.performed_by where r.equip_id = #{equipId} and r.due_date >= #{fromDate} and r.due_date <= #{toDate}
union all
select 'PART' as kind, p.part_id as src_id, coalesce(m.finished_at, p.created_at) as at, m.mwo_no as ref_no, i.item_cd || ' · ' || i.item_nm as title, null::varchar as status, null::varchar as sub_type, null::varchar as result, p.qty, p.unit_cd as unit, null::int as down_min, coalesce(u.user_nm, p.created_by) as by_nm, m.mwo_id from cms_mwo_part p join cms_mwo m on m.mwo_id = p.mwo_id join mst_item i on i.item_id = p.item_id left join sys_user u on u.login_id = p.created_by where m.equip_id = #{equipId} and m.status <> 'CANCELLED' and coalesce(m.finished_at, p.created_at) >= #{from} and coalesce(m.finished_at, p.created_at) < #{to}
union all
select 'RESET' as kind, r.reading_id as src_id, r.read_at as at, c.counter_cd as ref_no, c.counter_nm as title, null::varchar as status, null::varchar as sub_type, null::varchar as result, r.gauge_value as qty, c.unit_nm as unit, null::int as down_min, coalesce(u.user_nm, r.recorded_by) as by_nm, null::bigint as mwo_id from cms_counter_reading r join cms_counter c on c.counter_id = r.counter_id left join sys_user u on u.login_id = r.recorded_by where c.equip_id = #{equipId} and r.reset_yn = 'Y' and r.void_yn = 'N' and r.read_at >= #{from} and r.read_at < #{to}
) h
